    int keyLen = keyBytes.length;
    int valLen = valBytes.length;
    byte[] buf = new byte[1 + 4 + keyLen + 8 + 4 + valLen];
    int off = 0;

    // type
    buf[off++] = type;

    // keyLen (big-endian int)
    buf[off++] = (byte) (keyLen >>> 24);
    buf[off++] = (byte) (keyLen >>> 16);
    buf[off++] = (byte) (keyLen >>> 8);
    buf[off++] = (byte) keyLen;

    // key bytes
