 60→    private JlsmTable.StringKeyed buildTable(Path dir, JlsmSchema schema) throws IOException {
 61→        final MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
 62→        final TypedLsmTree.StringKeyed<JlsmDocument> tree = TypedStandardLsmTree
 63→                .<JlsmDocument>stringKeyedBuilder()
 64→                .wal(LocalWriteAheadLog.builder().directory(dir).build())
 65→                .memTableFactory(ConcurrentSkipListMemTable::new)
 66→                .sstableWriterFactory((SSTableWriterFactory) (id, level,
 67→                        path) -> new TrieSSTableWriter(id, level, path))
 68→                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
 69→                        BlockedBloomFilter.deserializer()))
 70→                .idSupplier(idCounter::getAndIncrement)
 71→                .pathFn((id, level) -> dir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
 72→                .memTableFlushThresholdBytes(1024 * 1024).valueSerializer(codec).build();
 73→        return StandardJlsmTable.stringKeyedBuilder().lsmTree(tree).schema(schema).build();
 74→    }
