package jlsm.table;

import jlsm.bloom.blocked.BlockedBloomFilter;
import jlsm.core.io.MemorySerializer;
import jlsm.core.tree.TypedLsmTree;
import jlsm.memtable.ConcurrentSkipListMemTable;
import jlsm.sstable.TrieSSTableReader;
import jlsm.sstable.TrieSSTableWriter;
import jlsm.table.internal.InProcessPartitionClient;
import jlsm.tree.SSTableReaderFactory;
import jlsm.tree.SSTableWriterFactory;
import jlsm.tree.TypedStandardLsmTree;
import jlsm.wal.local.LocalWriteAheadLog;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.lang.foreign.MemorySegment;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link PartitionedTable} — WU-3 coordinator.
 *
 * <p>
 * Uses real in-process LSM trees via {@link InProcessPartitionClient} to exercise end-to-end
 * routing, range fan-out, and lifecycle management.
 */
class PartitionedTableTest {

    @TempDir
    Path tempDir;

    private final AtomicLong idCounter = new AtomicLong(0);

    // -------------------------------------------------------------------------
    // Test helpers
    // -------------------------------------------------------------------------

    private static JlsmSchema testSchema() {
        return JlsmSchema.builder("test", 1)
                .field("name", FieldType.Primitive.STRING)
                .field("value", FieldType.Primitive.INT32)
                .build();
    }

    private static MemorySegment seg(String s) {
        return MemorySegment.ofArray(s.getBytes(StandardCharsets.UTF_8));
    }

    /** Builds a real JlsmTable.StringKeyed backed by an LSM tree in the given directory. */
    private JlsmTable.StringKeyed buildTable(Path dir, JlsmSchema schema) throws IOException {
        final MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
        final TypedLsmTree.StringKeyed<JlsmDocument> tree = TypedStandardLsmTree
                .<JlsmDocument>stringKeyedBuilder()
                .wal(LocalWriteAheadLog.builder().directory(dir).build())
                .memTableFactory(ConcurrentSkipListMemTable::new)
                .sstableWriterFactory((SSTableWriterFactory) (id, level,
                        path) -> new TrieSSTableWriter(id, level, path))
                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
                        BlockedBloomFilter.deserializer()))
                .idSupplier(idCounter::getAndIncrement)
                .pathFn((id, level) -> dir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
                .memTableFlushThresholdBytes(1024 * 1024)
                .valueSerializer(codec)
                .build();
        return StandardJlsmTable.stringKeyedBuilder().lsmTree(tree).schema(schema).build();
    }

    /**
     * Builds a two-partition setup: partition 1 = [a, m), partition 2 = [m, z{).
     *
     * <p>
     * Returns a PartitionedTable with both partitions backed by real LSM trees.
     * The caller is responsible for closing the returned table.
     */
    private PartitionedTable buildTwoPartitionTable(Path baseDir, JlsmSchema schema)
            throws IOException {
        final Path dir1 = baseDir.resolve("part1");
        final Path dir2 = baseDir.resolve("part2");
        Files.createDirectories(dir1);
        Files.createDirectories(dir2);

        final PartitionDescriptor desc1 = new PartitionDescriptor(1L, seg("a"), seg("m"),
                "local", 0L);
        final PartitionDescriptor desc2 = new PartitionDescriptor(2L, seg("m"), seg("{"),
                "local", 0L);
        // Note: '{' is ASCII 123, just above 'z' (122), so [m, {) covers m..z inclusive

        final PartitionConfig config = PartitionConfig.of(List.of(desc1, desc2));
        final JlsmTable.StringKeyed table1 = buildTable(dir1, schema);
        final JlsmTable.StringKeyed table2 = buildTable(dir2, schema);

        return PartitionedTable.builder()
                .partitionConfig(config)
                .schema(schema)
                .partitionClientFactory(desc -> {
                    if (desc.id() == 1L) return new InProcessPartitionClient(desc, table1);
                    if (desc.id() == 2L) return new InProcessPartitionClient(desc, table2);
                    throw new IllegalStateException("unexpected descriptor id: " + desc.id());
                })
                .build();
    }

    // -------------------------------------------------------------------------
    // Builder validation
    // -------------------------------------------------------------------------

    @Test
    void builder_missingConfig_throwsIllegalStateException() {
        final JlsmSchema schema = testSchema();
        assertThrows(IllegalStateException.class, () -> PartitionedTable.builder()
                .schema(schema)
                .partitionClientFactory(desc -> null)
                .build());
    }

    @Test
    void builder_missingFactory_throwsIllegalStateException() {
        final PartitionDescriptor desc = new PartitionDescriptor(1L, seg("a"), seg("z"),
                "local", 0L);
        final PartitionConfig config = PartitionConfig.of(List.of(desc));
        assertThrows(IllegalStateException.class, () -> PartitionedTable.builder()
                .partitionConfig(config)
                .build());
    }

    @Test
    void builder_nullConfig_throwsNullPointerException() {
        assertThrows(NullPointerException.class,
                () -> PartitionedTable.builder().partitionConfig(null));
    }

    @Test
    void builder_nullFactory_throwsNullPointerException() {
        assertThrows(NullPointerException.class,
                () -> PartitionedTable.builder().partitionClientFactory(null));
    }

    // -------------------------------------------------------------------------
    // config()
    // -------------------------------------------------------------------------

    @Test
    void config_returnsPartitionConfig() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("config_returns");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final PartitionConfig config = table.config();
            assertNotNull(config, "config must not be null");
            assertEquals(2, config.partitionCount(), "expected two partitions");
        }
    }

    // -------------------------------------------------------------------------
    // CRUD routing — single-key operations
    // -------------------------------------------------------------------------

    @Test
    void create_and_get_routesToCorrectPartition() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("crud_routing");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice", "value", 42);

            // 'b' is in partition 1 [a, m)
            table.create("b", doc);
            final Optional<JlsmDocument> result = table.get("b");
            assertTrue(result.isPresent(), "document should be found in correct partition");
            assertEquals("Alice", result.get().getString("name"));
        }
    }

    @Test
    void get_missingKey_returnsEmpty() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("get_missing");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final Optional<JlsmDocument> result = table.get("b");
            assertTrue(result.isEmpty(), "missing key should return empty");
        }
    }

    @Test
    void create_inPartition2_routesCorrectly() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("crud_part2");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument doc = JlsmDocument.of(schema, "name", "Zeus", "value", 99);

            // 'z' is in partition 2 [m, {)
            table.create("z", doc);
            final Optional<JlsmDocument> result = table.get("z");
            assertTrue(result.isPresent(), "document in partition 2 should be found");
            assertEquals("Zeus", result.get().getString("name"));
        }
    }

    @Test
    void create_duplicateKey_throwsDuplicateKeyException() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("crud_duplicate");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice", "value", 42);
            table.create("b", doc);

            assertThrows(DuplicateKeyException.class, () -> table.create("b", doc));
        }
    }

    @Test
    void update_routesToCorrectPartition() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("update_routing");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument original = JlsmDocument.of(schema, "name", "Alice", "value", 1);
            final JlsmDocument updated = JlsmDocument.of(schema, "name", "Alice B.", "value", 2);

            table.create("b", original);
            table.update("b", updated, UpdateMode.REPLACE);

            final Optional<JlsmDocument> result = table.get("b");
            assertTrue(result.isPresent());
            assertEquals("Alice B.", result.get().getString("name"));
            assertEquals(2, result.get().getInt("value"));
        }
    }

    @Test
    void delete_routesToCorrectPartition() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("delete_routing");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument doc = JlsmDocument.of(schema, "name", "Alice", "value", 1);
            table.create("b", doc);
            table.delete("b");

            final Optional<JlsmDocument> result = table.get("b");
            assertTrue(result.isEmpty(), "deleted key should return empty");
        }
    }

    @Test
    void create_keyOutsideAllRanges_throwsIllegalArgumentException() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("out_of_range");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final JlsmDocument doc = JlsmDocument.of(schema, "name", "OutOfRange", "value", 0);
            // '1' (ASCII 49) is below 'a' (ASCII 97) — outside all partition ranges
            assertThrows(IllegalArgumentException.class, () -> table.create("1", doc));
        }
    }

    // -------------------------------------------------------------------------
    // getRange — multi-partition fan-out
    // -------------------------------------------------------------------------

    @Test
    void getRange_withinSinglePartition_returnsCorrectEntries() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("range_single_part");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            table.create("a", JlsmDocument.of(schema, "name", "A", "value", 1));
            table.create("b", JlsmDocument.of(schema, "name", "B", "value", 2));
            table.create("c", JlsmDocument.of(schema, "name", "C", "value", 3));

            final Iterator<TableEntry<String>> it = table.getRange("a", "c");
            final List<String> keys = collectKeys(it);

            assertEquals(List.of("a", "b"), keys,
                    "half-open [a,c) should return a and b");
        }
    }

    @Test
    void getRange_acrossPartitions_mergesInKeyOrder() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("range_multi_part");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            // Insert keys spanning both partitions:
            //   partition 1 [a, m): e, f, g, k
            //   partition 2 [m, {): n, p, r
            table.create("e", JlsmDocument.of(schema, "name", "E", "value", 5));
            table.create("f", JlsmDocument.of(schema, "name", "F", "value", 6));
            table.create("g", JlsmDocument.of(schema, "name", "G", "value", 7));
            table.create("k", JlsmDocument.of(schema, "name", "K", "value", 11));
            table.create("n", JlsmDocument.of(schema, "name", "N", "value", 14));
            table.create("p", JlsmDocument.of(schema, "name", "P", "value", 16));
            table.create("r", JlsmDocument.of(schema, "name", "R", "value", 18));

            // Query [f, p) — spans both partitions; should include f,g,k,n
            final Iterator<TableEntry<String>> it = table.getRange("f", "p");
            final List<String> keys = collectKeys(it);

            assertEquals(List.of("f", "g", "k", "n"), keys,
                    "merged range [f,p) should return entries from both partitions in key order");
        }
    }

    @Test
    void getRange_emptyResult_returnsEmptyIterator() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("range_empty");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            table.create("z", JlsmDocument.of(schema, "name", "Z", "value", 99));

            final Iterator<TableEntry<String>> it = table.getRange("a", "b");
            assertFalse(it.hasNext(), "no entries in [a,b) should yield empty iterator");
        }
    }

    // -------------------------------------------------------------------------
    // query — throws UnsupportedOperationException
    // -------------------------------------------------------------------------

    @Test
    void query_throwsUnsupportedOperationException() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("query_unsupported");
        try (var table = buildTwoPartitionTable(baseDir, schema)) {
            final Predicate pred = new Predicate.Eq("name", "Alice");
            assertThrows(UnsupportedOperationException.class, () -> table.query(pred, 10));
        }
    }

    // -------------------------------------------------------------------------
    // Lifecycle — close()
    // -------------------------------------------------------------------------

    @Test
    void close_closesAllPartitionClients() throws IOException {
        final JlsmSchema schema = testSchema();
        final Path baseDir = tempDir.resolve("close_lifecycle");
        // Just verify close does not throw; double-close behavior is not specified
        final PartitionedTable table = buildTwoPartitionTable(baseDir, schema);
        assertDoesNotThrow(table::close);
    }

    @Test
    void close_withFailingClient_accumulatesAndThrows() throws IOException {
        final PartitionDescriptor desc1 = new PartitionDescriptor(1L, seg("a"), seg("m"),
                "local", 0L);
        final PartitionDescriptor desc2 = new PartitionDescriptor(2L, seg("m"), seg("{"),
                "local", 0L);
        final PartitionConfig config = PartitionConfig.of(List.of(desc1, desc2));

        // Client 1 throws on close, client 2 is a no-op — both close() must be called
        final boolean[] client2Closed = {false};
        final PartitionClient failingClient = new StubPartitionClient(desc1) {
            @Override
            public void close() throws IOException {
                throw new IOException("simulated close failure");
            }
        };
        final PartitionClient client2 = new StubPartitionClient(desc2) {
            @Override
            public void close() throws IOException {
                client2Closed[0] = true;
            }
        };

        final PartitionedTable table = PartitionedTable.builder()
                .partitionConfig(config)
                .partitionClientFactory(desc -> {
                    if (desc.id() == 1L) return failingClient;
                    return client2;
                })
                .build();

        final IOException thrown = assertThrows(IOException.class, table::close);
        assertTrue(client2Closed[0],
                "client 2 must be closed even when client 1 throws");
        assertNotNull(thrown, "an IOException must be thrown when a client fails to close");
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private List<String> collectKeys(Iterator<TableEntry<String>> it) {
        final List<String> keys = new ArrayList<>();
        while (it.hasNext()) {
            keys.add(it.next().key());
        }
        return keys;
    }

    /**
     * Minimal stub PartitionClient for lifecycle tests. All operation methods throw
     * UnsupportedOperationException by default; subclasses override only what they need.
     */
    private static abstract class StubPartitionClient implements PartitionClient {

        private final PartitionDescriptor descriptor;

        StubPartitionClient(PartitionDescriptor descriptor) {
            this.descriptor = descriptor;
        }

        @Override
        public PartitionDescriptor descriptor() {
            return descriptor;
        }

        @Override
        public void create(String key, JlsmDocument doc) throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public Optional<JlsmDocument> get(String key) throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public void delete(String key) throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public Iterator<TableEntry<String>> getRange(String fromKey, String toKey)
                throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
            throw new UnsupportedOperationException("stub");
        }

        @Override
        public void close() throws IOException {
            // no-op by default
        }
    }
}

package jlsm.table;

import jlsm.table.internal.RangeMap;
import jlsm.table.internal.ResultMerger;

import java.io.Closeable;
import java.io.IOException;
import java.lang.foreign.MemorySegment;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;

/**
 * Coordinator for a range-partitioned table.
 *
 * <p>
 * Contract: Routes key-based CRUD to the correct partition via O(log P) range map lookup. Executes
 * scatter-gather for multi-partition queries (vector, full-text, combined) and merges results. Each
 * partition is accessed through a {@link PartitionClient}, allowing future remote implementations
 * without changing the coordinator.
 *
 * <p>
 * Governed by: .decisions/table-partitioning/adr.md — range partitioning with per-partition
 * co-located indices.
 */
public final class PartitionedTable implements Closeable {

    private final PartitionConfig config;
    private final RangeMap rangeMap;
    // Ordered map: descriptor id → client (insertion order matches config order)
    private final Map<Long, PartitionClient> clients;

    private PartitionedTable(PartitionConfig config, RangeMap rangeMap,
            Map<Long, PartitionClient> clients) {
        assert config != null : "config must not be null";
        assert rangeMap != null : "rangeMap must not be null";
        assert clients != null : "clients must not be null";
        assert !clients.isEmpty() : "clients must not be empty";
        this.config = config;
        this.rangeMap = rangeMap;
        this.clients = clients;
    }

    /**
     * Returns a builder for constructing a partitioned table.
     *
     * @return a new builder
     */
    public static Builder builder() {
        return new Builder();
    }

    /**
     * Creates a document, routing to the correct partition by key.
     *
     * @param key the document key
     * @param doc the document to create
     * @throws IOException if the write fails
     * @throws DuplicateKeyException if the key already exists
     */
    public void create(String key, JlsmDocument doc) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        final PartitionClient client = routeKey(key);
        client.create(key, doc);
    }

    /**
     * Retrieves a document by key, routing to the correct partition.
     *
     * @param key the document key
     * @return the document, or empty if not found
     * @throws IOException if the read fails
     */
    public Optional<JlsmDocument> get(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        final PartitionClient client = routeKey(key);
        return client.get(key);
    }

    /**
     * Updates a document, routing to the correct partition by key.
     *
     * @param key the document key
     * @param doc the updated document
     * @param mode replace or patch
     * @throws IOException if the write fails
     */
    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        Objects.requireNonNull(mode, "mode must not be null");
        final PartitionClient client = routeKey(key);
        client.update(key, doc, mode);
    }

    /**
     * Deletes a document, routing to the correct partition by key.
     *
     * @param key the document key
     * @throws IOException if the write fails
     */
    public void delete(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        final PartitionClient client = routeKey(key);
        client.delete(key);
    }

    /**
     * Returns entries across partitions within the given key range, merged in key order.
     *
     * <p>
     * Routes to the minimal set of overlapping partitions and merges their iterators.
     *
     * @param fromKey inclusive lower bound
     * @param toKey exclusive upper bound
     * @return iterator over matching entries in key order
     * @throws IOException if any partition read fails
     */
    public Iterator<TableEntry<String>> getRange(String fromKey, String toKey) throws IOException {
        Objects.requireNonNull(fromKey, "fromKey must not be null");
        Objects.requireNonNull(toKey, "toKey must not be null");
        final MemorySegment fromSeg = toSegment(fromKey);
        final MemorySegment toSeg = toSegment(toKey);
        final List<PartitionDescriptor> overlapping = rangeMap.overlapping(fromSeg, toSeg);
        assert !overlapping.isEmpty() || true : "overlapping may be empty for non-overlapping range";

        final List<Iterator<TableEntry<String>>> iterators = new ArrayList<>(overlapping.size());
        for (final PartitionDescriptor desc : overlapping) {
            final PartitionClient client = clients.get(desc.id());
            assert client != null : "no client found for descriptor id " + desc.id();
            iterators.add(client.getRange(fromKey, toKey));
        }
        return ResultMerger.mergeOrdered(iterators);
    }

    /**
     * Executes a query across all relevant partitions and merges results.
     *
     * <p>
     * Per-partition predicate execution is not yet implemented — this method throws
     * {@link UnsupportedOperationException} until {@code InProcessPartitionClient.query()} is
     * implemented in a future work unit.
     *
     * @param predicate the query predicate
     * @param limit maximum results
     * @return scored results merged across partitions
     * @throws IOException if any partition query fails
     * @throws UnsupportedOperationException always — per-partition predicate execution is not yet
     *         implemented
     */
    public List<ScoredEntry<String>> query(Predicate predicate, int limit) throws IOException {
        Objects.requireNonNull(predicate, "predicate must not be null");
        if (limit <= 0) {
            throw new IllegalArgumentException("limit must be positive, got: " + limit);
        }
        throw new UnsupportedOperationException(
                "per-partition predicate execution is not yet implemented; "
                        + "InProcessPartitionClient.query() will be wired in a future work unit");
    }

    /**
     * Returns the partition configuration for this table.
     *
     * @return the partition config
     */
    public PartitionConfig config() {
        return config;
    }

    /**
     * Closes all partition clients. Uses the deferred close pattern: all clients are closed even if
     * one or more throw, and exceptions are accumulated. If any client fails to close, the first
     * exception is thrown with remaining exceptions added as suppressed.
     *
     * @throws IOException if any partition client fails to close
     */
    @Override
    public void close() throws IOException {
        IOException firstException = null;
        for (final PartitionClient client : clients.values()) {
            try {
                client.close();
            } catch (final IOException e) {
                if (firstException == null) {
                    firstException = e;
                } else {
                    firstException.addSuppressed(e);
                }
            }
        }
        if (firstException != null) {
            throw firstException;
        }
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    /**
     * Routes the given string key to its owning partition client.
     *
     * @param key the string key
     * @return the owning partition client
     * @throws IllegalArgumentException if the key falls outside all partition ranges
     */
    private PartitionClient routeKey(String key) {
        assert key != null : "key must not be null";
        final MemorySegment keySeg = toSegment(key);
        final PartitionDescriptor desc = rangeMap.routeKey(keySeg);
        final PartitionClient client = clients.get(desc.id());
        assert client != null : "no client registered for descriptor id " + desc.id();
        return client;
    }

    /**
     * Converts a string key to a {@link MemorySegment} in UTF-8 encoding for RangeMap routing.
     *
     * @param key the string key
     * @return the key as a MemorySegment
     */
    private static MemorySegment toSegment(String key) {
        assert key != null : "key must not be null";
        return MemorySegment.ofArray(key.getBytes(StandardCharsets.UTF_8));
    }

    // -------------------------------------------------------------------------
    // Builder
    // -------------------------------------------------------------------------

    /**
     * Builder for {@link PartitionedTable}.
     */
    public static final class Builder {

        private PartitionConfig config;
        private JlsmSchema schema;
        private Function<PartitionDescriptor, PartitionClient> factory;

        private Builder() {
        }

        /**
         * Sets the partition configuration.
         *
         * @param config the partition layout
         * @return this builder
         */
        public Builder partitionConfig(PartitionConfig config) {
            this.config = Objects.requireNonNull(config, "config must not be null");
            return this;
        }

        /**
         * Sets the schema shared by all partitions.
         *
         * @param schema the document schema
         * @return this builder
         */
        public Builder schema(JlsmSchema schema) {
            this.schema = schema; // optional — may be null
            return this;
        }

        /**
         * Sets the factory for creating partition clients. Called once per partition during build.
         *
         * @param factory function from PartitionDescriptor to PartitionClient
         * @return this builder
         */
        public Builder partitionClientFactory(
                Function<PartitionDescriptor, PartitionClient> factory) {
            this.factory = Objects.requireNonNull(factory, "factory must not be null");
            return this;
        }

        /**
         * Builds the partitioned table.
         *
         * <p>
         * Invokes the partition client factory once per descriptor in the configuration. All created
         * clients are owned by the returned {@link PartitionedTable} and closed when the table is
         * closed.
         *
         * @return the configured partitioned table
         * @throws IOException if any partition client fails to initialize
         * @throws IllegalStateException if partitionConfig or partitionClientFactory is not set
         */
        public PartitionedTable build() throws IOException {
            if (config == null) {
                throw new IllegalStateException("partitionConfig must be set before calling build()");
            }
            if (factory == null) {
                throw new IllegalStateException(
                        "partitionClientFactory must be set before calling build()");
            }

            final RangeMap rangeMap = new RangeMap(config);

            // Build clients in config order, using LinkedHashMap to preserve insertion order
            final Map<Long, PartitionClient> clients = new LinkedHashMap<>();
            for (final PartitionDescriptor desc : config.descriptors()) {
                final PartitionClient client = factory.apply(desc);
                Objects.requireNonNull(client,
                        "partitionClientFactory returned null for descriptor id " + desc.id());
                clients.put(desc.id(), client);
            }

            assert clients.size() == config.partitionCount() : "client count must match partition count";
            return new PartitionedTable(config, rangeMap, clients);
        }
    }
}

